-- 0732 · DGG-269 — Plantillas de campaña federal al estándar PREMIUM (pedido de Pablo).
-- Las 2 campañas federales (curso RPA CABA + consultoría jurídica) salían con el layout
-- base manaxer-v1 (logo+kicker+título+texto+CTA), SIN el banner-imagen premium ni el
-- botón de WhatsApp que ya usan las campañas de captación (dgg220, ver 0553). Pablo:
-- "no tiene los banners premium... no tiene el botón de contactar por WhatsApp. Mejoralo."
--
-- Igualamos la vara de 0553_dgg220_copy_v2_negritas_wa: cuerpo_html_visual con
--   (1) preheader oculto · (2) banner-imagen (public/email/federal-*.png, generados con
--   marketing/email-banners/gg-mail-banner-themed.mjs: RPA=theme curso + co-brand Gestar;
--   consultoría=theme legal/balanza nuevo) · (3) copy con {{nombre}} en negrita ·
--   (4) caja destacada #E7F1F9 borde cian · (5) botón de marca #009ECA + botón WhatsApp
--   #25D366 con wa-icon.png "¿Lo charlamos?" y prefill por campaña.
-- Se vacían cta_text/cta_url para que buildManaxerHtml NO duplique el CTA (ambos botones
-- viven en el cuerpo, igual que en captación). Kicker/título/acento/logo/firma intactos.
-- Los banners quedan servidos en https://www.gestionglobal.ar/email/federal-*.png (Vercel).
-- Sigue GATED: federal_campanas_activo OFF; esto sólo cambia el diseño, no dispara nada.

UPDATE public.email_templates SET
  cta_text = '', cta_url = '',
  cuerpo_html_visual = $gg$<div style="display:none;max-height:0;overflow:hidden;opacity:0;mso-hide:all;">El curso que habilita tu renovación en CABA — modalidad mixta, en vivo y a tu ritmo, con certificado válido ante el Registro.</div><img src="https://www.gestionglobal.ar/email/federal-rpa-caba.png" alt="Curso de Actualización RPA · CABA · Gestar · Gestión Global" width="576" style="display:block;width:100%;max-width:576px;height:auto;border-radius:12px;margin:2px 0 22px;" /><p style="margin:0 0 14px;">Hola <strong>{{nombre}}</strong>. Si administrás en la Ciudad de Buenos Aires, el <strong>Curso de Actualización RPA (CABA)</strong> es el que te <strong>habilita a renovar tu matrícula</strong>: el certificado es válido ante el Registro.</p><p style="margin:0 0 14px;">Lo cursás en <strong>modalidad mixta</strong>: clases <strong>en vivo</strong> para resolver dudas con los docentes y clases <strong>asincrónicas</strong> (grabadas) para ver cuando te quede cómodo. En alianza académica con <strong>Gestar</strong>, con el sello de Gestión Global.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:0 0 18px;background:#E7F1F9;border-left:4px solid #009ECA;border-radius:8px;"><tr><td style="padding:14px 16px;font-size:14.5px;line-height:1.6;color:#0B1F33;">Modalidad mixta (en vivo + asincrónicas), <strong>certificado habilitante</strong> para renovar tu matrícula en CABA y <strong>ebooks exclusivos</strong> para alumnos. La cursada la hacés a tu ritmo; el certificado te queda listo para el Registro.</td></tr></table><p style="margin:0 0 4px;">Adelantarte es sacarte el pendiente de encima con tiempo. Vos seguí administrando; de la formación que te habilita nos ocupamos nosotros —aliados de tu tiempo.</p><table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:22px 0 2px;"><tr><td style="padding-bottom:11px;"><a href="https://www.gestionglobal.ar/formulario/curso-actualizacion-caba" target="_blank" rel="noopener" style="display:inline-block;background:#009ECA;border-radius:10px;padding:13px 24px;font-size:14.5px;font-weight:700;color:#ffffff;text-decoration:none;">Quiero inscribirme</a></td></tr><tr><td><a href="https://api.whatsapp.com/send/?phone=+5492214317914&text=Hola%21%20Recib%C3%AD%20el%20mail%20y%20me%20interesa%20el%20Curso%20de%20Actualizaci%C3%B3n%20RPA%20%28CABA%29" target="_blank" rel="noopener" style="display:inline-block;background:#25D366;border-radius:10px;padding:12px 20px;text-decoration:none;"><img src="https://www.gestionglobal.ar/email/wa-icon.png" width="17" height="17" alt="WhatsApp" style="vertical-align:-3px;margin-right:9px;" /><span style="color:#ffffff;font-size:14px;font-weight:700;">¿Lo charlamos?</span></a></td></tr></table>$gg$,
  updated_at = now()
WHERE slug = 'federal-rpa-caba';

UPDATE public.email_templates SET
  cta_text = '', cta_url = '',
  cuerpo_html_visual = $gg$<div style="display:none;max-height:0;overflow:hidden;opacity:0;mso-hide:all;">Un equipo especializado en propiedad horizontal para consultar cuando lo necesites, en todo el país.</div><img src="https://www.gestionglobal.ar/email/federal-consultoria.png" alt="Consultoría Jurídica de propiedad horizontal · Gestión Global" width="576" style="display:block;width:100%;max-width:576px;height:auto;border-radius:12px;margin:2px 0 22px;" /><p style="margin:0 0 14px;">Hola <strong>{{nombre}}</strong>. Administrar consorcios es, muchas veces, resolver temas legales: una asamblea impugnada, un reglamento que interpretar, un conflicto con un propietario, un contrato para revisar.</p><p style="margin:0 0 14px;">Con la <strong>Consultoría Jurídica de Gestión Global</strong> tenés un equipo especializado en <strong>propiedad horizontal</strong> para consultar cuando lo necesites — sin importar en qué provincia administres.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:0 0 18px;background:#E7F1F9;border-left:4px solid #009ECA;border-radius:8px;"><tr><td style="padding:14px 16px;font-size:14.5px;line-height:1.6;color:#0B1F33;">Especialistas en propiedad horizontal, <strong>respuestas claras sin letra chica</strong> y cobertura en todo el país. Un respaldo legal a tu lado, para las dudas del día a día y para los temas que no pueden esperar.</td></tr></table><p style="margin:0 0 4px;">No tenés que resolver en soledad lo que pide una mirada jurídica. Vos administrás; del respaldo legal nos ocupamos nosotros —aliados de tu tiempo.</p><table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:22px 0 2px;"><tr><td style="padding-bottom:11px;"><a href="https://www.gestionglobal.ar/formulario/consultoria-juridica" target="_blank" rel="noopener" style="display:inline-block;background:#009ECA;border-radius:10px;padding:13px 24px;font-size:14.5px;font-weight:700;color:#ffffff;text-decoration:none;">Quiero asesorarme</a></td></tr><tr><td><a href="https://api.whatsapp.com/send/?phone=+5492214317914&text=Hola%21%20Recib%C3%AD%20el%20mail%20y%20quiero%20asesorarme%20con%20la%20Consultor%C3%ADa%20Jur%C3%ADdica" target="_blank" rel="noopener" style="display:inline-block;background:#25D366;border-radius:10px;padding:12px 20px;text-decoration:none;"><img src="https://www.gestionglobal.ar/email/wa-icon.png" width="17" height="17" alt="WhatsApp" style="vertical-align:-3px;margin-right:9px;" /><span style="color:#ffffff;font-size:14px;font-weight:700;">¿Lo charlamos?</span></a></td></tr></table>$gg$,
  updated_at = now()
WHERE slug = 'federal-consultoria';
